{
  "findings": [
    {
      "check_id": "CKV_AWS_23",
      "title": "Security group rules missing description",
      "resource": "aws_security_group.lb",
      "severity": "MEDIUM",
      "explanation": "The ingress and egress rules do not have descriptions, which makes auditing and understanding the purpose of these open rules difficult."
    },
    {
      "check_id": "CKV_AWS_382",
      "title": "Unrestricted Egress Traffic",
      "resource": "aws_security_group.lb",
      "severity": "HIGH",
      "explanation": "The egress rule allows all traffic (protocol -1) to any destination (0.0.0.0/0), which can facilitate data exfiltration or malware communication if the resource is compromised."
    },
    {
      "check_id": "CKV_AWS_277",
      "title": "Unrestricted Ingress Traffic",
      "resource": "aws_security_group.lb",
      "severity": "CRITICAL",
      "explanation": "The ingress rule allows all traffic (protocol -1) from any source (0.0.0.0/0). This exposes the associated resources to the entire internet on all ports and protocols, creating a severe security risk."
    }
  ],
  "patched_code": "resource \"aws_security_group\" \"lb\" {\n  name   = \"allow-all-lb\"\n  vpc_id = data.aws_vpc.main.id\n\n  # WARNING: The original configuration allowed ALL ingress/egress from/to ANYWHERE.\n  # This is a critical security misconfiguration. \n  # Below are placeholders for restricted access. You MUST replace the CIDR blocks \n  # and ports with values appropriate for your specific Load Balancer use case.\n  # For example, an ALB might only need port 443 from 0.0.0.0/0.\n\n  ingress {\n    description = \"Allow HTTPS from Internet\"\n    from_port   = 443\n    to_port     = 443\n    protocol    = \"tcp\"\n    cidr_blocks = [\"0.0.0.0/0\"] # TODO: Restrict if possible, or ensure this is intended for public LB\n  }\n\n  egress {\n    description = \"Allow outbound traffic to VPC\"\n    from_port   = 0\n    to_port     = 0\n    protocol    = \"-1\"\n    cidr_blocks = [\"10.0.0.0/8\"] # TODO: Replace with actual VPC CIDR or specific target SGs\n  }\n}",
  "fix_summary": "Added descriptions to all security group rules. Replaced the overly permissive 'all traffic' ingress rule with a restricted TCP 443 rule (common for LBs) and added a TODO comment. Replaced the unrestricted egress rule with one scoped to the VPC CIDR range (placeholder) to prevent uncontrolled outbound traffic. Note: Specific ports/CIDRs must be adjusted based on actual application requirements."
}
